{
  "metric": "trips",
  "target_window": "2024-11-28",
  "baseline_window": "2024-11-07, 2024-11-14, 2024-11-21 (prior 3 Thursdays)",
  "hypotheses": [
    {
      "id": "H0",
      "kind": "metric",
      "statement": "Yellow taxi trips on Thursday 28 Nov 2024 dropped significantly compared to the average of the prior three Thursdays (7, 14, 21 Nov 2024).",
      "support_if": "Trips on 2024-11-28 are at least 20% below the mean of 2024-11-07, 2024-11-14, 2024-11-21.",
      "refute_if": "Trips on 2024-11-28 are within 5% of the prior-Thursday mean."
    },
    {
      "id": "H1",
      "kind": "holiday",
      "statement": "Thanksgiving (a federal holiday on 28 Nov 2024) suppressed demand because many residents leave the city and businesses close.",
      "support_if": "2024-11-28 is flagged as a federal holiday in whybot.us_holidays and trip count is far below the non-holiday Thursday baseline.",
      "refute_if": "2024-11-28 is not a holiday, or holiday Thursdays in the data show no systematic dip."
    },
    {
      "id": "H2",
      "kind": "weather",
      "statement": "Adverse weather (rain, snow, or cold) on 28 Nov 2024 reduced street-hail and dispatch demand.",
      "support_if": "whybot.nyc_weather_daily shows measurable precipitation (prcp_mm > 5 or snow_mm > 0) or tmax_c near/below freezing on 2024-11-28, while baseline Thursdays were dry and milder.",
      "refute_if": "Weather on 2024-11-28 was similar to or better than baseline Thursdays."
    },
    {
      "id": "H3",
      "kind": "day_of_week",
      "statement": "The drop is not unique to 28 Nov; Thursdays in late November 2024 show a general downward trend unrelated to the holiday.",
      "support_if": "A linear trend over Thursdays 2024-11-07 through 2024-11-28 shows a steady decline, and 28 Nov fits the trend.",
      "refute_if": "28 Nov is a sharp negative outlier relative to the Thursday trend."
    },
    {
      "id": "H4",
      "kind": "fare_mix",
      "statement": "The composition of trips shifted toward shorter/cheaper rides (e.g., fewer airport trips), lowering total trip count if drivers idle more.",
      "support_if": "avg_trip_distance and avg_total_amount on 2024-11-28 are materially lower than on baseline Thursdays.",
      "refute_if": "avg_trip_distance and avg_total_amount on 2024-11-28 are within 5% of baseline Thursday averages."
    },
    {
      "id": "H5",
      "kind": "data_quality",
      "statement": "The apparent drop is an artifact of missing or delayed TLC records for 28 Nov 2024.",
      "support_if": "TPCDS_DB.date_dim shows no data-quality flags, but whybot.yellow_daily has an implausibly low row count or null metrics for 2024-11-28 compared to adjacent days.",
      "refute_if": "Metrics for 2024-11-28 are present and internally consistent (non-null, non-zero trips, reasonable averages)."
    }
  ],
  "queries": [
    {
      "hypothesis_id": "H0",
      "purpose": "Return trips for target Thursday 2024-11-28 and the three prior Thursdays (2024-11-07, 2024-11-14, 2024-11-21) to quantify the drop.",
      "tables": ["whybot.yellow_daily", "TPCDS_DB.date_dim"]
    },
    {
      "hypothesis_id": "H1",
      "purpose": "Confirm 2024-11-28 is a federal holiday (Thanksgiving) and check whether other federal-holiday Thursdays in the dataset show similar trip suppression.",
      "tables": ["whybot.yellow_daily", "whybot.us_holidays", "TPCDS_DB.date_dim"]
    },
    {
      "hypothesis_id": "H2",
      "purpose": "Fetch precipitation (prcp_mm), snowfall (snow_mm), and max temperature (tmax_c) for 2024-11-28 and the three baseline Thursdays.",
      "tables": ["whybot.nyc_weather_daily", "TPCDS_DB.date_dim"]
    },
    {
      "hypothesis_id": "H3",
      "purpose": "Get trips for all Thursdays in November 2024 (2024-11-07, 14, 21, 28) to assess trend vs. outlier.",
      "tables": ["whybot.yellow_daily", "TPCDS_DB.date_dim"]
    },
    {
      "hypothesis_id": "H4",
      "purpose": "Compare avg_trip_distance and avg_total_amount on 2024-11-28 vs. the three baseline Thursdays.",
      "tables": ["whybot.yellow_daily", "TPCDS_DB.date_dim"]
    },
    {
      "hypothesis_id": "H5",
      "purpose": "Check data completeness for 2024-11-28: non-null trips, avg_trip_distance, avg_total_amount; also verify no gap in surrounding days.",
      "tables": ["whybot.yellow_daily", "TPCDS_DB.date_dim"]
    }
  ],
  "rationale": "H0 quantifies the metric change against a like-for-like weekday baseline. H1 tests the obvious Thanksgiving effect using the authoritative holiday table. H2 checks for weather impact with Central Park observations. H3 distinguishes a one-day holiday shock from a broader Thursday trend. H4 examines fare/distance mix shifts that could indicate behavioral change. H5 rules out data-quality artifacts. All queries stay within the 2024-04-01..2025-02-28 window and use only catalog tables."
}

{
  "sql": "SELECT y.trip_date, y.trips AS trips, d.d_day_name AS day_name FROM whybot.yellow_daily y JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date WHERE y.trip_date IN (DATE '2024-11-07', DATE '2024-11-14', DATE '2024-11-21', DATE '2024-11-28') ORDER BY d.d_dow, y.trip_date",
  "tables_used": ["whybot.yellow_daily", "TPCDS_DB.date_dim"],
  "note": "Returns one row per requested Thursday with trip count and weekday name. Uses conditional date literals and explicit JOIN on date key per Zetaris quirks."
}

{
  "sql": "SELECT y.trip_date, y.trips, d.d_day_name, h.holiday_name, MAX(CASE WHEN y.trip_date = DATE '2024-11-28' THEN y.trips END) OVER () AS target_trips, AVG(CASE WHEN y.trip_date <> DATE '2024-11-28' THEN y.trips END) OVER () AS baseline_avg_trips FROM whybot.yellow_daily y JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date LEFT JOIN whybot.us_holidays h ON h.holiday_date = y.trip_date WHERE y.trip_date BETWEEN DATE '2024-11-01' AND DATE '2024-11-30' AND d.d_dow = 5 ORDER BY y.trip_date",
  "tables_used": ["whybot.yellow_daily", "TPCDS_DB.date_dim", "whybot.us_holidays"],
  "note": "d_dow=5 maps to Thursday; filters to November 2024; conditional aggregation compares target vs baseline across the month"
}

{
  "sql": "SELECT y.trip_date, w.prcp_mm, w.snow_mm, w.tmax_c, d.d_day_name FROM whybot.yellow_daily y JOIN whybot.nyc_weather_daily w ON w.obs_date = y.trip_date JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date WHERE y.trip_date BETWEEN DATE '2024-11-01' AND DATE '2024-11-30' AND d.d_dow = 4 ORDER BY y.trip_date",
  "tables_used": [
    "whybot.yellow_daily",
    "whybot.nyc_weather_daily",
    "TPCDS_DB.date_dim"
  ],
  "note": "Baseline Thursdays in Nov 2024: 7, 14, 21, 28. d_dow=4 maps to Thursday (1=Sunday..7=Saturday)."
}

{
  "sql": "SELECT y.trip_date, y.trips, d.d_day_name FROM whybot.yellow_daily y JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date WHERE d_dow = 4 AND y.trip_date BETWEEN DATE '2024-11-01' AND DATE '2024-11-30' ORDER BY y.trip_date",
  "tables_used": ["whybot.yellow_daily", "TPCDS_DB.date_dim"],
  "note": "Selects trips for all Thursdays in November 2024 (d_dow=4 maps to Thursday). Output is 4 rows ordered by date."
}

{
  "sql": "SELECT y.trip_date, y.trips, y.avg_trip_distance AS avg_dist, y.avg_total_amount AS avg_amount, d.d_day_name FROM whybot.yellow_daily y JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date WHERE y.trip_date BETWEEN DATE '2024-11-25' AND DATE '2024-12-02' ORDER BY y.trip_date",
  "tables_used": [
    "whybot.yellow_daily",
    "TPCDS_DB.date_dim"
  ],
  "note": "Shows trips, avg_trip_distance, avg_total_amount for 2024-11-28 and surrounding days with weekday names"
}

