{
  "sql": "SELECT y.trip_date, y.trips, h.holiday_name, d.d_day_name FROM whybot.yellow_daily y LEFT JOIN whybot.us_holidays h ON h.holiday_date = y.trip_date JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date WHERE d.d_dow = 5 AND h.is_national = TRUE AND y.trip_date BETWEEN DATE '2024-04-01' AND DATE '2025-02-28' ORDER BY y.trip_date",
  "tables_used": [
    "whybot.yellow_daily",
    "whybot.us_holidays",
    "TPCDS_DB.date_dim"
  ],
  "note": "LEFT JOIN from yellow_daily ensures all days appear; d_dow=5 matches Thursday; is_national=TRUE filters federal holidays only."
}

